insert into items (id, nivel, tipo, grupo, orden_grupo, instruccion_ja, enunciado, objetivo, opciones, respuesta, logica_distractores, explicacion, puntos, pasaje, guion, audio, etiquetas, dificultad) values
  ('n2-bunpou1-0001', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼は仕事が忙しい（　）、会議には必ず出席する。', null, '["ものの", "ために", "おかげで", "ばかりに"]'::jsonb, 0, '["ためには理由", "おかげでは good cause", "ばかりにはbad cause"]'::jsonb, '{"es": "〜ものの = «aunque», concesivo. Los otros tres son de causa, y aquí no hay causa sino contraste.", "en": "〜ものの = ''although'', concessive. The other three mark cause, but this sentence contrasts rather than explains."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0002', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '一度引き受けた（　）、最後までやり遂げるつもりだ。', null, '["からには", "ところで", "とはいえ", "どころか"]'::jsonb, 0, '["ところでは逆接", "とはいえは逆接", "どころかは否定強調"]'::jsonb, '{"es": "〜からには = «ya que…, entonces por fuerza». Introduce la determinación que sigue.", "en": "〜からには = ''now that…, then of course''. It sets up the resolve that follows."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0003', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '今さら先生に言われた（　）、勉強する気にはなれない。', null, '["ところで", "からこそ", "ばかりに", "とともに"]'::jsonb, 0, '["からこそは肯定的理由", "ばかりにはbad cause", "とともには同時"]'::jsonb, '{"es": "〜たところで = «aunque me lo digan, da igual». Siempre lleva un resultado negativo o inútil.", "en": "〜たところで = ''even if they tell me, it won''t help''. It always leads to a futile or negative result."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0004', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼の実力（　）、優勝は当然の結果と言える。', null, '["からすれば", "にしては", "どころか", "において"]'::jsonb, 0, '["にしてはは期待外れ", "どころかは否定強調", "においては場面"]'::jsonb, '{"es": "〜からすれば = «a juzgar por». にしては diría lo contrario: que el resultado no cuadra con su nivel.", "en": "〜からすれば = ''judging from''. にしては would say the opposite: that the result doesn''t match his level."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0005', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '体調が悪いので、今回の出張は見送らざる（　）。', null, '["を得ない", "にすぎない", "ようがない", "ほかならない"]'::jsonb, 0, '["にすぎないは程度", "ようがないは手段の不在", "ほかならないは断定"]'::jsonb, '{"es": "〜ざるを得ない = «no queda más remedio que». Se une a la forma ない sin el ない: 見送らざるを得ない.", "en": "〜ざるを得ない = ''have no choice but to''. It attaches to the ない-stem: 見送らざるを得ない."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0006', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼は忙しい忙しいと言い（　）、毎晩飲みに行っている。', null, '["つつ", "ばかり", "きり", "がち"]'::jsonb, 0, '["ばかりは限定", "きりは以来", "がちは傾向"]'::jsonb, '{"es": "〜つつ = «mientras dice…, en realidad». Marca contradicción entre lo que se dice y lo que se hace.", "en": "〜つつ = ''while saying…, actually''. It marks the gap between what is said and what is done."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0007', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'あの店は値段が高い（　）、味は確かだ。', null, '["だけあって", "どころか", "ばかりか", "にしては"]'::jsonb, 0, '["どころかは否定強調", "ばかりかは追加", "にしてはは期待外れ"]'::jsonb, '{"es": "〜だけあって = «como corresponde a lo caro que es». El precio justifica la calidad.", "en": "〜だけあって = ''as befits how expensive it is''. The price justifies the quality."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0008', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '連絡先が分からないので、知らせ（　）がない。', null, '["よう", "もの", "こと", "ところ"]'::jsonb, 0, '["ものは物事", "ことは事柄", "ところは場所や場面"]'::jsonb, '{"es": "〜ようがない = «no hay manera de». Se forma con la raíz masu: 知らせ＋ようがない.", "en": "〜ようがない = ''there''s no way to''. Built on the masu-stem: 知らせ＋ようがない."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0009', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '小学生（　）、ずいぶん難しい言葉を知っているね。', null, '["にしては", "としては", "にしても", "において"]'::jsonb, 0, '["としてはは立場", "にしてもは譲歩", "においては場面"]'::jsonb, '{"es": "〜にしては = «para ser…, sorprende». Marca que la realidad no cuadra con lo esperado de esa categoría.", "en": "〜にしては = ''for a…, surprisingly''. It flags that reality doesn''t match what the category leads you to expect."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0010', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '試験に受かるかどうかは、これからの努力（　）だ。', null, '["次第", "ばかり", "きり", "まま"]'::jsonb, 0, '["ばかりは限定", "きりは以来", "ままは状態の維持"]'::jsonb, '{"es": "〜次第だ = «depende de». Lo que va delante decide el resultado.", "en": "〜次第だ = ''depends on''. What comes before decides the outcome."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0011', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '準備が終わらない（　）、始めるわけにはいかない。', null, '["ことには", "ものなら", "どころか", "かぎりで"]'::jsonb, 0, '["ものならは仮定", "どころかは否定強調", "かぎりでは範囲"]'::jsonb, '{"es": "〜ないことには = «si no…, entonces no». Condición imprescindible, siempre en negativo.", "en": "〜ないことには = ''unless…, then not''. An indispensable condition, always negative."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou1-0012', 'N2', 'bunpou1', null, 0, '次の文の（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'この本は読めば読む（　）、面白くなってくる。', null, '["ほど", "だけ", "まま", "きり"]'::jsonb, 0, '["だけは限定", "ままは維持", "きりは以来"]'::jsonb, '{"es": "〜ば〜ほど = «cuanto más…, más». La estructura pide 読めば読むほど.", "en": "〜ば〜ほど = ''the more…, the more''. The pattern requires 読めば読むほど."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-bunpou2-0001', 'N2', 'bunpou2', null, 0, '次の文の ＿★＿ に入る最もよいものを、1・2・3・4から一つ選びなさい。', 'この計画は ＿＿ ＿★＿ ＿＿ ＿＿ 中止になった。', '住民 の 反対 により', '["の", "反対", "住民", "により"]'::jsonb, 0, '[]'::jsonb, '{"es": "El orden es 住民の反対により («por la oposición de los vecinos»). En el ★, segunda casilla, va の.", "en": "The order is 住民の反対により (''because of the residents'' opposition''). The ★, the second slot, takes の."}'::jsonb, null, null, null, null, '["orden"]'::jsonb, 3),
  ('n2-bunpou2-0002', 'N2', 'bunpou2', null, 0, '次の文の ＿★＿ に入る最もよいものを、1・2・3・4から一つ選びなさい。', '彼は ＿＿ ＿★＿ ＿＿ ＿＿ 諦めなかった。', '何度 も 失敗したの に', '["に", "何度", "も", "失敗したの"]'::jsonb, 2, '[]'::jsonb, '{"es": "El orden es 何度も失敗したのに («aunque falló muchas veces»). En el ★ va も.", "en": "The order is 何度も失敗したのに (''even though he failed many times''). も goes in the ★."}'::jsonb, null, null, null, null, '["orden"]'::jsonb, 3),
  ('n2-bunpou2-0003', 'N2', 'bunpou2', null, 0, '次の文の ＿★＿ に入る最もよいものを、1・2・3・4から一つ選びなさい。', '日本語は ＿＿ ＿★＿ ＿＿ ＿＿ 難しくなる。', '勉強 すれば する ほど', '["ほど", "勉強", "すれば", "する"]'::jsonb, 2, '[]'::jsonb, '{"es": "El orden es 勉強すればするほど («cuanto más estudias»). En el ★ va すれば.", "en": "The order is 勉強すればするほど (''the more you study''). すれば goes in the ★."}'::jsonb, null, null, null, null, '["orden"]'::jsonb, 3),
  ('n2-bunpou2-0004', 'N2', 'bunpou2', null, 0, '次の文の ＿★＿ に入る最もよいものを、1・2・3・4から一つ選びなさい。', '先生の ＿＿ ＿★＿ ＿＿ ＿＿ 合格できた。', '助言 の おかげ で', '["おかげ", "で", "助言", "の"]'::jsonb, 3, '[]'::jsonb, '{"es": "El orden es 助言のおかげで («gracias al consejo»). En el ★ va の.", "en": "The order is 助言のおかげで (''thanks to the advice''). の goes in the ★."}'::jsonb, null, null, null, null, '["orden"]'::jsonb, 3),
  ('n2-bunpou2-0005', 'N2', 'bunpou2', null, 0, '次の文の ＿★＿ に入る最もよいものを、1・2・3・4から一つ選びなさい。', 'あの店は ＿＿ ＿★＿ ＿＿ ＿＿ 味がいい。', '値段が 高い だけ あって', '["だけ", "高い", "あって", "値段が"]'::jsonb, 1, '[]'::jsonb, '{"es": "El orden es 値段が高いだけあって («como corresponde a lo caro que es»). En el ★ va 高い.", "en": "The order is 値段が高いだけあって (''as befits how pricey it is''). 高い goes in the ★."}'::jsonb, null, null, null, null, '["orden"]'::jsonb, 3),
  ('n2-sokuji-0001', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'この資料、明日までにお願いできますか。', null, '["はい、承知しました。", "はい、お願いします。", "いいえ、けっこうです。"]'::jsonb, 0, '["依頼を受けた側が「お願いします」とは言わない", "断り方として不自然"]'::jsonb, '{"es": "Te están pidiendo algo: se acepta con 承知しました. Decir お願いします sería devolverle el encargo.", "en": "You''re being asked to do something: accept with 承知しました. Saying お願いします would hand the job back."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "この資料、明日までにお願いできますか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0002', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '今日はごちそうさまでした。', null, '["いただきます。", "お粗末さまでした。", "ごちそうさまです。"]'::jsonb, 1, '["食べる前の挨拶", "相手の言葉をそのまま返している"]'::jsonb, '{"es": "Quien ha invitado responde お粗末さまでした. いただきます se dice antes de comer.", "en": "The host replies お粗末さまでした. いただきます is said before eating, not after."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "今日はごちそうさまでした。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0003', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '会議、そろそろ始めてもよろしいでしょうか。', null, '["ええ、どうぞ。", "ええ、始めました。", "いいえ、始めません。"]'::jsonb, 0, '["許可を求められているのに過去形", "主語がずれている"]'::jsonb, '{"es": "Piden permiso, así que se concede con どうぞ. 始めました contestaría a otra pregunta.", "en": "They''re asking permission, so grant it with どうぞ. 始めました would answer a different question."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "会議、そろそろ始めてもよろしいでしょうか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0004', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'その件でしたら、私がやっておきましょうか。', null, '["では、お願いできますか。", "では、やっておきました。", "では、やらないでください。"]'::jsonb, 0, '["申し出に過去形で答えている", "申し出を断る理由がない"]'::jsonb, '{"es": "Se están ofreciendo: se acepta con お願いできますか.", "en": "They''re offering to help: accept with お願いできますか."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "その件でしたら、私がやっておきましょうか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0005', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '田中さん、なんだか顔色がよくないですね。', null, '["ええ、ちょっと寝不足で。", "ええ、色を変えました。", "ええ、よく見えます。"]'::jsonb, 0, '["顔色を文字通りの「色」と取った", "意味が通らない"]'::jsonb, '{"es": "顔色がよくない = tienes mala cara. La opción 2 entiende 色 literalmente como un color.", "en": "顔色がよくない = you look unwell. Option 2 takes 色 literally as a colour."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "田中さん、なんだか顔色がよくないですね。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0006', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'すみません、道に迷ってしまって。', null, '["じゃあ、迎えに行きましょうか。", "じゃあ、道を作りましょうか。", "じゃあ、迷ってください。"]'::jsonb, 0, '["文字通りすぎる", "命令として意味が通らない"]'::jsonb, '{"es": "Se ha perdido: lo natural es ofrecerse a ir a buscarlo.", "en": "They''re lost: the natural reply is to offer to come and get them."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "すみません、道に迷ってしまって。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0007', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '部長は、もう帰られましたか。', null, '["ええ、さっき出られましたよ。", "ええ、もうすぐ来られます。", "ええ、帰ってきました。"]'::jsonb, 0, '["時間の向きが逆", "主語がずれている"]'::jsonb, '{"es": "帰られましたか es honorífico: «¿ya se ha ido?». La 2 dice que está por llegar, lo contrario.", "en": "帰られましたか is honorific: ''has he left yet?''. Option 2 says he''s about to arrive — the opposite."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "部長は、もう帰られましたか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0008', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '明日の打ち合わせ、少し遅れるかもしれません。', null, '["では、お先に始めておきますね。", "では、早く来てくださいね。", "では、遅れないでください。"]'::jsonb, 0, '["avisar no es pedir permiso", "責める返事になっている"]'::jsonb, '{"es": "Avisan de que llegarán tarde: se responde adaptándose, no regañando.", "en": "They''re warning they''ll be late: you respond by adapting, not by scolding."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "明日の打ち合わせ、少し遅れるかもしれません。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0009', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'これ、ちょっと味見してみてくれない?', null, '["うん、ちょっともらうね。", "うん、見るだけね。", "うん、作っておくね。"]'::jsonb, 0, '["味見の「見」を文字通りに取った", "頼まれていないこと"]'::jsonb, '{"es": "味見する = probar, no mirar. La 2 se queda en el 見 literal.", "en": "味見する = to taste, not to look. Option 2 gets stuck on the literal 見."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "これ、ちょっと味見してみてくれない?"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0010', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'エアコンをつけてもかまいませんか。', null, '["ええ、かまいます。", "ええ、どうぞ。", "いいえ、つけました。"]'::jsonb, 1, '["かまいませんの肯定形は使わない", "否定と過去が矛盾"]'::jsonb, '{"es": "A 〜てもかまいませんか se contesta どうぞ. «かまいます» no se usa como respuesta afirmativa.", "en": "To 〜てもかまいませんか you answer どうぞ. ''かまいます'' isn''t used as an affirmative reply."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "エアコンをつけてもかまいませんか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0011', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '山田さん、この漢字の読み方、分かる?', null, '["うーん、ちょっと自信ないな。", "うーん、読んでおいたよ。", "うーん、書いてあるよ。"]'::jsonb, 0, '["質問に答えていない", "質問に答えていない"]'::jsonb, '{"es": "Preguntan si lo sabe: se admite la duda. Las otras dos hablan de otra cosa.", "en": "They ask whether you know it: admit the doubt. The other two talk about something else."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "F", "texto": "山田さん、この漢字の読み方、分かる?"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-sokuji-0012', 'N2', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', '先週の出張、どうでしたか。', null, '["はい、行ってきます。", "思ったより収穫がありました。", "来週の予定です。"]'::jsonb, 1, '["これから行く言い方", "時期が違う"]'::jsonb, '{"es": "Preguntan por un viaje ya hecho. 行ってきます es para irse ahora y 来週 cambia la fecha.", "en": "They ask about a trip already made. 行ってきます is for leaving now, and 来週 changes the date."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "先週の出張、どうでしたか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 3),
  ('n2-kadai-0001', 'N2', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '男の人はこの後まず何をしますか。', null, '["資料を追加で印刷する", "部長に内容を確認する", "会議室の予約を延長する", "参加者に連絡する"]'::jsonb, 2, '["印刷は確認の後", "部長は今いない", "連絡は話に出ていない"]'::jsonb, '{"es": "Hacen falta más copias, pero antes el jefe quiere corregir algo — y ahora está reunido. Lo único que puede hacer ya es ampliar la reserva de la sala.", "en": "More copies are needed, but the boss wants to change something first — and he''s in a meeting. The only thing left to do right now is extend the room booking."}'::jsonb, '["部数が足りない → hay que imprimir más", "その前に部長が直したい → imprimir va después de la revisión", "さっき会議室に入った → ahora no se le puede preguntar", "それまでに予約を延長して → esto es lo inmediato"]'::jsonb, null, '{"intro": "男の人と女の人が会社で話しています。男の人はこの後まず何をしますか。", "turnos": [{"quien": "F", "texto": "田中さん、明日の会議の資料、もうできてる?"}, {"quien": "M", "texto": "はい、印刷もしておきました。"}, {"quien": "F", "texto": "ああ、ちょっと待って。参加者が二人増えたから、部数が足りないかも。"}, {"quien": "M", "texto": "じゃあ、追加で印刷しますね。"}, {"quien": "F", "texto": "うん。でも、その前に部長が内容を一か所直したいって言ってたから、確認してから印刷して。"}, {"quien": "M", "texto": "わかりました。部長、今いらっしゃいますか。"}, {"quien": "F", "texto": "さっき会議室に入ったから、終わるまで待ったほうがいいわ。それまでに会議室の予約を延長しておいてくれる?"}, {"quien": "M", "texto": "はい。"}], "pregunta": "男の人はこの後まず何をしますか。", "opciones_habladas": false}'::jsonb, null, '["課題理解", "職場"]'::jsonb, 3),
  ('n2-kadai-0002', 'N2', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '女の人はこれから何を買いますか。', null, '["絵の具とノート", "ノートと鉛筆", "鉛筆と筆", "筆とノート"]'::jsonb, 1, '["絵の具は持っている", "筆は先生が貸してくれる", "筆は借りられる"]'::jsonb, '{"es": "Se van descartando: las pinturas ya las tiene, los pinceles los presta el profesor. Quedan el cuaderno y un lápiz blando.", "en": "Things get ruled out one by one: she already has the paints, the teacher lends the brushes. That leaves the notebook and a soft pencil."}'::jsonb, '["絵の具は去年のがある → no hay que comprarlas", "筆は先生が貸してくれる → tampoco", "ノートは新しいのが要る → sí", "鉛筆は柔らかいのを → sí"]'::jsonb, null, '{"intro": "女の人と男の人が話しています。女の人はこれから何を買いますか。", "turnos": [{"quien": "F", "texto": "来週から絵の教室に通うんだけど、何を用意したらいいかな。"}, {"quien": "M", "texto": "絵の具は持ってる?"}, {"quien": "F", "texto": "うん、去年買ったのがまだ残ってる。"}, {"quien": "M", "texto": "じゃあ大丈夫。筆は最初の授業で先生が貸してくれるはずだよ。"}, {"quien": "F", "texto": "そうなんだ。じゃあ、あとはノートくらいかな。"}, {"quien": "M", "texto": "うん、それと鉛筆。下書きに使うから、柔らかいのを一本ね。"}, {"quien": "F", "texto": "分かった、その二つを買っておく。"}], "pregunta": "女の人はこれから何を買いますか。", "opciones_habladas": false}'::jsonb, null, '["課題理解", "買い物"]'::jsonb, 3),
  ('n2-tanbun-0001', 'N2', 'tanbun', 'n2-tanbun-g001', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者は、収納を工夫することについてどのように考えているか。', null, '["片づけの第一歩として、まず取り組むべきだ", "物を捨てずに済ませてしまうので、片づけとは逆の結果になりうる", "収納用品を買えば、半年で部屋がきれいになる", "片づけ方を知らない人には向いていない"]'::jsonb, 1, '["本文と逆", "調査結果を逆に読んでいる", "本文にない"]'::jsonb, '{"es": "El texto dice que cuantos más recipientes se compran, peor está el cuarto medio año después, porque uno acaba no tirando nada. La opción 3 lee el estudio al revés.", "en": "The text says the more containers people buy, the worse the room is six months later, because they end up throwing nothing away. Option 3 reads the study backwards."}'::jsonb, '["収納用品を買い足した家庭ほど半年後の状態が悪い → comprar cajas empeora la cosa", "入れ物が増えれば捨てずに済む → esa es la razón", "似ているようで正反対 → la tesis"]'::jsonb, '{"texto": "「片づけが苦手だ」と言う人の多くは、実は片づけ方を知らないのではなく、物を減らす決心がつかないだけらしい。ある調査によると、収納用品を買い足した家庭ほど、半年後の部屋の状態が悪くなっていたという。入れ物が増えれば、捨てずに済んでしまうからだ。つまり、収納を工夫することと片づけることは、似ているようで正反対の行為なのかもしれない。", "notas": [{"termino": "収納用品", "glosa": "物をしまうための箱や棚"}]}'::jsonb, null, null, '["随筆"]'::jsonb, 3),
  ('n2-tanbun-0002', 'N2', 'tanbun', 'n2-tanbun-g002', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '「勇気の問題に見えて、実は環境の問題なのだ」とあるが、どういうことか。', null, '["間違いを恐れない強い気持ちを持つことが何より大切だということ", "間違えても困らない相手がいるかどうかで、恐れの大きさが変わるということ", "外国語は環境のよい国で学ぶべきだということ", "助言をする人の態度に問題があるということ"]'::jsonb, 1, '["筆者が役に立たないと言っている助言そのもの", "「環境」を国のことだと文字通りに取った", "本文にない"]'::jsonb, '{"es": "Para el autor el miedo no se quita por voluntad, sino que se encoge solo cuando hay alguien que te repregunta y te corrige sin dramas. La 3 toma «entorno» como país, que no es lo que dice.", "en": "For the author fear doesn''t go away by willpower; it shrinks on its own when someone asks again and corrects you without fuss. Option 3 takes ''environment'' to mean country, which isn''t what''s said."}'::jsonb, '["恐れは意志で消せない → el consejo habitual no sirve", "間違えても困らない場所を用意する → la propuesta", "聞き返してくれる相手がいれば恐れは小さくなる → el porqué"]'::jsonb, '{"texto": "外国語を学ぶとき、間違いを恐れるなとよく言われる。しかし私は、恐れるなという助言はあまり役に立たないと思っている。恐れは意志で消せるものではないからだ。それよりも、間違えても困らない場所を先に用意するほうがいい。聞き返してくれる相手、笑って直してくれる相手がいれば、恐れは自然に小さくなる。勇気の問題に見えて、実は環境の問題なのだ。", "notas": []}'::jsonb, null, null, '["随筆", "比喩"]'::jsonb, 4),
  ('n2-chuubun-0001', 'N2', 'chuubun', 'n2-chuubun-g001', 0, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '先輩に叱られたのは、どんなことに対してか。', null, '["大きな失敗をしたこと", "困った時点で報告しなかったこと", "報告の仕方が丁寧でなかったこと", "仕事が終わるのが遅かったこと"]'::jsonb, 1, '["本文が「失敗そのものではなかった」と否定している", "本文にない", "本文にない"]'::jsonb, '{"es": "El texto dice expresamente que no le riñeron por el error, sino por avisar cuando ya había terminado en vez de cuando surgió el problema.", "en": "The text says outright that he wasn''t told off for the mistake, but for reporting once it was over instead of when the trouble started."}'::jsonb, '["叱られたのは失敗そのものではなかった → no fue por el error", "困った時点で言え → fue por el momento del aviso"]'::jsonb, '{"texto": "会社に入ったばかりのころ、先輩に「報告は早いほどいい」と言われた。私はそれを、仕事が終わったらすぐ知らせろという意味だと受け取っていた。実際、しばらくはそのつもりで働いていたし、それで困ったこともなかった。\nところがある日、大きな失敗をして報告が遅れたとき、先輩に叱られたのは失敗そのものではなかった。「終わってから言うな、困った時点で言え」と言われたのだ。自分では、きちんと片をつけてから伝えるほうが迷惑をかけないと思っていたのだが、先輩の顔を見て、その考えが逆であることに気づいた。\n考えてみれば当然である。終わった仕事の報告は、聞く側にとってはただの記録にすぎない。しかし途中の報告は、まだ手の打ちようがある情報だ。前者は過去の話で、後者は未来の話なのだ。記録は後からでも読めるが、未来の話は、その時に聞かなければ意味を失う。\nそれ以来、私は「順調です」という報告をしないことにしている。順調なら黙っていても誰も困らない。報告が必要なのは、いつも順調でないときのほうなのだから。", "notas": [{"termino": "手の打ちよう", "glosa": "対処する方法"}]}'::jsonb, null, null, '["随筆", "職場"]'::jsonb, 4),
  ('n2-chuubun-0002', 'N2', 'chuubun', 'n2-chuubun-g001', 1, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '「前者は過去の話で、後者は未来の話なのだ」とあるが、「後者」とは何か。', null, '["終わった仕事の報告", "途中の報告", "先輩の助言", "失敗の記録"]'::jsonb, 1, '["前者のほう", "本文の別の要素", "本文の別の要素"]'::jsonb, '{"es": "前者 es el informe de un trabajo ya terminado y 後者 el informe a medio camino, que todavía permite reaccionar.", "en": "前者 is the report on finished work and 後者 the mid-way report, which still allows you to act."}'::jsonb, '["終わった仕事の報告＝前者", "途中の報告＝後者、まだ手の打ちようがある"]'::jsonb, null, null, null, '["随筆", "職場"]'::jsonb, 4),
  ('n2-chuubun-0003', 'N2', 'chuubun', 'n2-chuubun-g001', 2, '次の文章を読んで、後の問いに対する答えとして最もよいものを、1・2・3・4から一つ選びなさい。', '筆者が「順調です」という報告をしないのはなぜか。', null, '["順調なときは報告する時間がないから", "順調でないときこそ報告が必要だと考えているから", "先輩にそう命じられたから", "報告が多いと迷惑をかけるから"]'::jsonb, 1, '["本文にない", "先輩の言葉は別の内容", "本文にない"]'::jsonb, '{"es": "Su conclusión es que si todo va bien no pasa nada por callar; el informe hace falta justo cuando las cosas no van bien.", "en": "His conclusion is that when things go well silence costs nothing; the report is needed precisely when they don''t."}'::jsonb, '["順調なら黙っていても困らない", "報告が必要なのは順調でないときのほう"]'::jsonb, null, null, null, '["随筆", "職場"]'::jsonb, 4),
  ('n2-kanji_yomi-0001', 'N2', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '彼の提案は会議で採用された。', '採用', '["さいよう", "さいよ", "ざいよう", "さいゆう"]'::jsonb, 0, '["長音を落とした", "濁音にした", "母音を変えた"]'::jsonb, '{"es": "採用（さいよう）. 採 se lee さい y 用 よう. El error más común es comerse el alargamiento: さいよ.", "en": "採用 (saiyō). 採 is さい and 用 よう. The usual slip is dropping the long vowel: さいよ."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-kanji_yomi-0002', 'N2', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', 'この道は工事のため通行止めになっている。', '通行', '["つうこう", "つこう", "とうこう", "つうごう"]'::jsonb, 0, '["長音なし", "通をとうと読んだ", "行を濁音にした"]'::jsonb, '{"es": "通行（つうこう）. 通 en compuestos es つう, no とう; y lleva vocal larga.", "en": "通行 (tsūkō). In compounds 通 is つう, never とう, and the vowel is long."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-kanji_yomi-0003', 'N2', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '彼女は毎日欠かさず日記をつけている。', '欠かさず', '["かかさず", "なくさず", "きらさず", "たやさず"]'::jsonb, 0, '["同じ活用の別動詞", "同じ活用の別動詞", "同じ活用の別動詞"]'::jsonb, '{"es": "欠かす→欠かさず（かかさず）, «sin faltar un solo día». Los otros tres son verbos distintos con la misma terminación.", "en": "欠かす → 欠かさず (kakasazu), ''without missing a day''. The other three are different verbs with the same ending."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-kanji_yomi-0004', 'N2', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '険しい山道を三時間かけて登った。', '険しい', '["けわしい", "きびしい", "はげしい", "くやしい"]'::jsonb, 0, '["厳しいと混同", "激しいと混同", "悔しいと混同"]'::jsonb, '{"es": "険しい（けわしい）= escarpado. きびしい es 厳しい, はげしい es 激しい: adjetivos de la misma forma pero otro kanji.", "en": "険しい (kewashii) = steep. きびしい is 厳しい and はげしい is 激しい — same shape, different kanji."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-kanji_yomi-0005', 'N2', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '新しい制度の導入が検討されている。', '導入', '["どうにゅう", "とうにゅう", "どうにゅ", "どうじゅう"]'::jsonb, 0, '["清音にした", "長音を落とした", "入をじゅうと読んだ"]'::jsonb, '{"es": "導入（どうにゅう）. 導 es どう (sonoro) y 入 にゅう con vocal larga.", "en": "導入 (dōnyū). 導 is どう (voiced) and 入 is にゅう with a long vowel."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-kanji_yomi-0006', 'N2', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '駅前の商店街は夕方になると賑わう。', '商店街', '["しょうてんがい", "しょてんがい", "しょうてんかい", "しょてんかい"]'::jsonb, 0, '["長音なし", "連濁なし", "両方"]'::jsonb, '{"es": "商店街（しょうてんがい）. 商 lleva vocal larga y 街 se sonoriza a がい tras 店.", "en": "商店街 (shōtengai). 商 has a long vowel and 街 voices to がい after 店."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-hyouki-0001', 'N2', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', '毎朝走るのはけんこうのためだ。', 'けんこう', '["健康", "建康", "健庫", "建庫"]'::jsonb, 0, '["建と健の混同", "康と庫の混同", "両方"]'::jsonb, '{"es": "健康. 健 (persona sana) no 建 (construir); 康 no 庫 (almacén). Se parecen mucho de forma.", "en": "健康. 健 (healthy) not 建 (build); 康 not 庫 (warehouse). They look very similar."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-hyouki-0002', 'N2', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', '先生のこうぎはとても分かりやすい。', 'こうぎ', '["講義", "構義", "購義", "講議"]'::jsonb, 0, '["同じ部首の講/構", "同じ部首の購", "義と議の混同"]'::jsonb, '{"es": "講義 = clase magistral. 講/構/購 comparten forma; 義 (sentido) no 議 (deliberar).", "en": "講義 = a lecture. 講/構/購 look alike; 義 (meaning) not 議 (to deliberate)."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-hyouki-0003', 'N2', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', '書類の最後にしょめいをしてください。', 'しょめい', '["署名", "暑名", "諸名", "署明"]'::jsonb, 0, '["暑と署の混同", "諸と署の混同", "名と明の混同"]'::jsonb, '{"es": "署名 = firma. 署 (oficina, firmar) no 暑 (calor) ni 諸 (varios).", "en": "署名 = signature. 署 (office, to sign) not 暑 (hot) or 諸 (various)."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-hyouki-0004', 'N2', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', '彼がいがいにも早く着いたので驚いた。', 'いがい', '["意外", "以外", "意害", "異外"]'::jsonb, 0, '["以外との混同", "害と外の混同", "異と意の混同"]'::jsonb, '{"es": "意外 = inesperado. 以外 (いがい) existe pero significa «excepto»: es el fallo clásico del N2.", "en": "意外 = unexpected. 以外 (igai) also exists but means ''except'' — the classic N2 trap."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-hyouki-0005', 'N2', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', 'この機械はそうさが簡単だ。', 'そうさ', '["操作", "捜査", "創作", "装作"]'::jsonb, 0, '["同音の捜査", "そうさくとの混同", "存在しない語"]'::jsonb, '{"es": "操作 = manejo de una máquina. 捜査 (そうさ) es «investigación policial»; 創作 se lee そうさく.", "en": "操作 = operating a machine. 捜査 (sōsa) is a police investigation; 創作 reads sōsaku."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-gokeisei-0001', 'N2', 'gokeisei', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'その情報はまだ（　）公式のもので、発表はされていない。', '（　）公式', '["非", "未", "無", "不"]'::jsonb, 0, '["未は「まだ〜していない」", "無は「〜がない」", "不は否定一般"]'::jsonb, '{"es": "非公式 = extraoficial. 非〜 niega la naturaleza de algo; 未〜 es «todavía no» y 無〜 es «sin».", "en": "非公式 = unofficial. 非〜 negates what something is; 未〜 means ''not yet'' and 無〜 means ''without''."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
