  ('n2-gokeisei-0003', 'N2', 'gokeisei', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '工事は（　）完成のまま中断されている。', '（　）完成', '["未", "非", "無", "反"]'::jsonb, 0, '["非は性質の否定", "無は不在", "反は反対"]'::jsonb, '{"es": "未完成 = sin terminar. 未〜 dice que algo aún no ha llegado a ese estado.", "en": "未完成 = unfinished. 未〜 says something has not yet reached that state."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-gokeisei-0004', 'N2', 'gokeisei', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '先月より電気（　）が高くなった。', '電気（　）', '["代", "費", "料", "賃"]'::jsonb, 0, '["費は支出全般", "料は料金の語基", "賃は労働や運送"]'::jsonb, '{"es": "電気代 = la factura de la luz. 〜代 es lo que se paga por algo consumido; 〜賃 es por transporte o trabajo.", "en": "電気代 = the electricity bill. 〜代 is what you pay for something consumed; 〜賃 is for transport or labour."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
  ('n2-gokeisei-0005', 'N2', 'gokeisei', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', '彼は責任（　）が強く、仕事を最後までやり遂げる。', '責任（　）', '["感", "性", "心", "力"]'::jsonb, 0, '["性は性質", "心は気持ち一般", "力は能力"]'::jsonb, '{"es": "責任感 = sentido de la responsabilidad. 〜感 es la sensación interna; 〜性 sería una propiedad objetiva.", "en": "責任感 = a sense of responsibility. 〜感 is the inner feeling; 〜性 would be an objective property."}'::jsonb, null, null, null, null, '[]'::jsonb, 3),
