  ('n5-sokuji-0006', 'N5', 'sokuji', null, 0, '問題では、問題用紙に何も印刷されていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。', 'きのうの テスト、どうでしたか。', null, '["むずかしかったです。", "あしたです。", "はい、します。"]'::jsonb, 0, '["日が違う", "はい/いいえの質問ではない"]'::jsonb, '{"es": "どうでしたか pide una impresión en pasado.", "en": "どうでしたか asks for an impression in the past tense."}'::jsonb, null, null, '{"intro": "", "turnos": [{"quien": "M", "texto": "きのうの テスト、どうでしたか。"}], "pregunta": "", "opciones_habladas": true}'::jsonb, null, '["即時応答"]'::jsonb, 1),
  ('n5-kadai-0001', 'N5', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '女の人は これから 何を 買いますか。', null, '["たまごと ぎゅうにゅう", "ぎゅうにゅうと パン", "たまごと パン", "パンだけ"]'::jsonb, 1, '["たまごは 家に ある", "たまごは 買わない", "パンだけでは 足りない"]'::jsonb, '{"es": "Los huevos ya los tiene en casa, así que solo compra leche y pan.", "en": "She already has eggs at home, so she only buys milk and bread."}'::jsonb, '["たまごは まだ あります → no hay que comprarlos", "ぎゅうにゅうが ありません → sí", "パンも おねがい → sí"]'::jsonb, null, '{"intro": "男の人と 女の人が 話しています。女の人は これから 何を 買いますか。", "turnos": [{"quien": "M", "texto": "これから かいものに 行くんだけど、何か いる?"}, {"quien": "F", "texto": "そうね、たまごは まだ ありますか。"}, {"quien": "M", "texto": "うん、五つ あるよ。"}, {"quien": "F", "texto": "じゃあ、たまごは いいです。ぎゅうにゅうが ありませんから、それを おねがいします。"}, {"quien": "M", "texto": "わかった。パンは?"}, {"quien": "F", "texto": "あ、パンも おねがいします。"}], "pregunta": "女の人は これから 何を 買いますか。", "opciones_habladas": false}'::jsonb, null, '["課題理解", "買い物"]'::jsonb, 2),
  ('n5-kadai-0002', 'N5', 'kadai', null, 0, '問題では、まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。', '男の学生は はじめに 何を しますか。', null, '["本を 読む", "しゅくだいを 出す", "先生に 電話する", "うちへ 帰る"]'::jsonb, 1, '["読むのは あとで", "先生は 教室に いる", "帰るのは さいご"]'::jsonb, '{"es": "El profesor está en el aula, así que primero entrega los deberes; leer es para después.", "en": "The teacher is in the classroom, so first he hands in the homework; reading comes later."}'::jsonb, '["先生は 教室に います → se le puede entregar ya", "しゅくだいを 出してから → primero eso", "本は うちで 読みます → después"]'::jsonb, null, '{"intro": "女の学生と 男の学生が 話しています。男の学生は はじめに 何を しますか。", "turnos": [{"quien": "F", "texto": "しゅくだい、もう 出しましたか。"}, {"quien": "M", "texto": "いいえ、まだです。先生は どこですか。"}, {"quien": "F", "texto": "先生は 教室に いますよ。"}, {"quien": "M", "texto": "じゃあ、しゅくだいを 出してから、としょかんへ 行きます。"}, {"quien": "F", "texto": "本を かりるんですか。"}, {"quien": "M", "texto": "ええ。でも 読むのは うちです。"}], "pregunta": "男の学生は はじめに 何を しますか。", "opciones_habladas": false}'::jsonb, null, '["課題理解", "学校"]'::jsonb, 2),
  ('n5-kanji_yomi-0001', 'N5', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', 'まいあさ 八じに 学校へ 行きます。', null, '["がっこう", "がくこう", "かっこう", "がっこ"]'::jsonb, 0, '["促音にしない", "清音にした", "長音を落とした"]'::jsonb, '{"es": "学校（がっこう）. 学 se acorta a がっ ante 校: es el 促音, la pausa breve.", "en": "学校 (gakkō). 学 shortens to がっ before 校 — that''s the small pause, the 促音."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-kanji_yomi-0002', 'N5', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '先生に しつもんを しました。', null, '["せんせい", "せいせい", "せんせ", "ぜんせい"]'::jsonb, 0, '["先をせいと読んだ", "長音を落とした", "濁音にした"]'::jsonb, '{"es": "先生（せんせい）. 先 es せん y 生 せい, las dos con vocal larga.", "en": "先生 (sensei). 先 is せん and 生 is せい, both with a long vowel."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-kanji_yomi-0003', 'N5', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '毎日 いぬと さんぽします。', null, '["まいにち", "まいひ", "めいにち", "まいじつ"]'::jsonb, 0, '["日を訓で読んだ", "毎をめいと読んだ", "日をじつと読んだ"]'::jsonb, '{"es": "毎日（まいにち）. En este compuesto 日 se lee にち, no ひ ni じつ.", "en": "毎日 (mainichi). In this compound 日 reads にち, not ひ or じつ."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-kanji_yomi-0004', 'N5', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', 'きょうは 天気が いいです。', null, '["てんき", "でんき", "てんぎ", "てんけ"]'::jsonb, 0, '["電気と混同", "気を濁音にした", "気をけと読んだ"]'::jsonb, '{"es": "天気（てんき）= el tiempo. でんき con voz sonora sería 電気, «electricidad».", "en": "天気 (tenki) = the weather. Voiced でんき would be 電気, ''electricity''."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-kanji_yomi-0005', 'N5', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', 'くだものを 食べるのが すきです。', null, '["たべる", "しょくべる", "かべる", "のべる"]'::jsonb, 0, '["音読みを使った", "別の訓", "別の訓"]'::jsonb, '{"es": "食べる（たべる）. しょく es la lectura on, que se usa en compuestos como 食堂.", "en": "食べる (taberu). しょく is the on reading, used in compounds like 食堂."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-kanji_yomi-0006', 'N5', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', '出口は あちらです。', null, '["でぐち", "でくち", "しゅつぐち", "でこう"]'::jsonb, 0, '["連濁なし", "音読みにした", "口をこうと読んだ"]'::jsonb, '{"es": "出口（でぐち）. 口 se sonoriza a ぐち tras 出: es el 連濁.", "en": "出口 (deguchi). 口 voices to ぐち after 出 — that''s rendaku."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-kanji_yomi-0007', 'N5', 'kanji_yomi', null, 0, '＿＿の言葉の読み方として最もよいものを、1・2・3・4から一つ選びなさい。', 'へやに 一人で います。', null, '["ひとり", "いちにん", "ひとにん", "いちひと"]'::jsonb, 0, '["音読みにした", "訓と音を混ぜた", "訓と音を混ぜた"]'::jsonb, '{"es": "一人（ひとり）es una lectura especial que hay que memorizar, como 二人（ふたり）.", "en": "一人 (hitori) is a special reading you simply memorise, like 二人 (futari)."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-hyouki-0001', 'N5', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', 'あしたは がっこうが やすみです。', null, '["学校", "学枚", "字校", "字枚"]'::jsonb, 0, '["校と枚の混同", "学と字の混同", "両方"]'::jsonb, '{"es": "学校. 校 (escuela) no 枚 (contador de hojas); 学 (estudiar) no 字 (carácter).", "en": "学校. 校 (school) not 枚 (counter for flat things); 学 (study) not 字 (character)."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-hyouki-0002', 'N5', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', 'この みずは つめたいです。', null, '["水", "氷", "永", "木"]'::jsonb, 0, '["氷は「こおり」", "永は「ながい」", "形が似ている"]'::jsonb, '{"es": "水 = agua. 氷 (hielo), 永 (eterno) y 木 (árbol) se parecen mucho de trazo.", "en": "水 = water. 氷 (ice), 永 (eternal) and 木 (tree) look very similar."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-hyouki-0003', 'N5', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', 'でんしゃで かいしゃへ 行きます。', null, '["電車", "電単", "田車", "田単"]'::jsonb, 0, '["車と単の混同", "電と田の混同", "両方"]'::jsonb, '{"es": "電車. 電 lleva 雨 arriba; 田 solo es el campo de arroz.", "en": "電車. 電 has 雨 on top; 田 is just the rice field."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-hyouki-0004', 'N5', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', 'この かばんは ちいさいです。', null, '["小さい", "少さい", "大さい", "小しい"]'::jsonb, 0, '["少は「すくない」", "反対の意味", "送り仮名が違う"]'::jsonb, '{"es": "小さい. 少 se lee すくない y significa «poco», no «pequeño».", "en": "小さい. 少 reads sukunai and means ''few'', not ''small''."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-hyouki-0005', 'N5', 'hyouki', null, 0, '＿＿の言葉を漢字で書くとき、最もよいものを、1・2・3・4から一つ選びなさい。', 'ともだちと はなしました。', null, '["話しました", "語しました", "言しました", "詰しました"]'::jsonb, 0, '["語は「かたる」", "言は「いう」", "形が似ている"]'::jsonb, '{"es": "話す = hablar (con alguien). 語る y 言う existen pero se leen distinto.", "en": "話す = to talk (with someone). 語る and 言う exist but read differently."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-bunmyaku-0001', 'N5', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'へやが あついので、まどを（　）ください。', null, '["あけて", "しめて", "けして", "つけて"]'::jsonb, 0, '["反対の動作", "電気などに使う", "電気などに使う"]'::jsonb, '{"es": "あつい → まどをあける. しめる sería lo contrario, y けす/つける van con la luz.", "en": "It''s hot → open the window. しめる is the opposite, and けす/つける go with lights."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-bunmyaku-0002', 'N5', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'そらが くろいです。（　）が ふりそうです。', null, '["あめ", "かぜ", "そら", "つき"]'::jsonb, 0, '["風は「ふく」", "降るものではない", "降るものではない"]'::jsonb, '{"es": "ふる se usa con あめ o ゆき. El viento no «cae»: かぜが ふく.", "en": "ふる goes with rain or snow. Wind doesn''t ''fall'': かぜが ふく."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-bunmyaku-0003', 'N5', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'わたしは まいあさ 六じに（　）。', null, '["おきます", "ねます", "かえります", "つきます"]'::jsonb, 0, '["反対の動作", "時間帯が合わない", "目的地が必要"]'::jsonb, '{"es": "六じにおきます = me levanto a las seis. ねる sería acostarse.", "en": "六じにおきます = I get up at six. ねる would be going to bed."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-bunmyaku-0004', 'N5', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'ふゆの かわの みずは とても（　）です。', null, '["つめたい", "あたたかい", "おもい", "ながい"]'::jsonb, 0, '["反対の意味", "重さの話", "長さの話"]'::jsonb, '{"es": "つめたい se dice de lo frío al tacto: agua, manos, bebidas.", "en": "つめたい is for things cold to the touch: water, hands, drinks."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-bunmyaku-0005', 'N5', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'じしょで ことばの いみを（　）。', null, '["しらべます", "つくります", "あそびます", "ならべます"]'::jsonb, 0, '["作る対象ではない", "共起しない", "共起しない"]'::jsonb, '{"es": "じしょでしらべる es la colocación fija: buscar en el diccionario.", "en": "じしょでしらべる is the fixed collocation: to look something up in the dictionary."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-bunmyaku-0006', 'N5', 'bunmyaku', null, 0, '（　）に入れるのに最もよいものを、1・2・3・4から一つ選びなさい。', 'あさごはんを たべる まえに、かおを（　）。', null, '["あらいます", "みがきます", "ふきます", "けします"]'::jsonb, 0, '["歯に使う", "ぬれた後に使う", "共起しない"]'::jsonb, '{"es": "かおをあらう = lavarse la cara. みがく se usa con los dientes o los zapatos.", "en": "かおをあらう = to wash your face. みがく goes with teeth or shoes."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-iikae-0001', 'N5', 'iikae', null, 0, '＿＿の文とだいたい同じ意味の文があります。1・2・3・4から一つ選びなさい。', 'この もんだいは やさしいです。', null, '["この もんだいは かんたんです。", "この もんだいは むずかしいです。", "この もんだいは ながいです。", "この もんだいは おおいです。"]'::jsonb, 0, '["反対の意味", "長さの話", "数の話"]'::jsonb, '{"es": "やさしい (fácil) = かんたん. Ojo: やさしい también puede ser «amable», pero con もんだい es «fácil».", "en": "やさしい (easy) = かんたん. Note: やさしい can also mean ''kind'', but with もんだい it means ''easy''."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-iikae-0002', 'N5', 'iikae', null, 0, '＿＿の文とだいたい同じ意味の文があります。1・2・3・4から一つ選びなさい。', 'この へやは しずかでは ありません。', null, '["この へやは うるさいです。", "この へやは きれいです。", "この へやは ひろいです。", "この へやは あかるいです。"]'::jsonb, 0, '["きれいさの話", "広さの話", "明るさの話"]'::jsonb, '{"es": "しずかではない = うるさい. Los otros tres hablan de otra propiedad de la habitación.", "en": "しずかではない = noisy. The other three describe a different property of the room."}'::jsonb, null, null, null, null, '[]'::jsonb, 1),
  ('n5-iikae-0003', 'N5', 'iikae', null, 0, '＿＿の文とだいたい同じ意味の文があります。1・2・3・4から一つ選びなさい。', 'テストは あしたの あさです。', null, '["テストは あしたの ごぜんです。", "テストは あしたの ごごです。", "テストは きょうの あさです。", "テストは あさっての あさです。"]'::jsonb, 0, '["時間帯が逆", "日が違う", "日が違う"]'::jsonb, '{"es": "あさ = ごぜん (por la mañana). ごご sería por la tarde.", "en": "あさ = ごぜん (morning). ごご would be the afternoon."}'::jsonb, null, null, null, null, '[]'::jsonb, 1)
